using System;
using System.Collections.Generic;
using System.Linq;

class Solution {
    static void Main(string[] args) {
        string[] input = Console.ReadLine().Split(' ');
        int[][] a = new int[8][];
        for (int i = 0; i < 8; i++) {
            a[i] = Array.ConvertAll(input[i].Split(' '), int.Parse);
        }
        int b = 10, w = 10;
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j++) {
                if (a[i][j] == 1) {
                    int f = 0;
                    for (int k = i + 1; k < 8; k++) {
                        if (a[k][j] == 1 || a[k][j] == 0) f = 1;
                    }
                    if (!f) b = Math.Min(8 - i - 1, b);
                }
                if (a[i][j] == 2) {
                    int f = 0;
                    for (int k = i - 1; k >= 0; k--) {
                        if (a[k][j] != 0) f = 1;
                    }
                    if (!f) w = Math.Min(i, w);
                }
            }
        }
        Console.WriteLine(b < w ? "B" : "A");
    }
}
