#include <stdio.h>
#include <string.h>

// Function to tokenize the input string
void tokenize(char* input, char** tokens) {
    char* token = strtok(input, " ");
    while (token != NULL) {
        tokens = (char**)realloc(tokens, (strlen(tokens) + 5) * sizeof(char*));
        tokens[strlen(tokens) - 1] = token;
        token = strtok(NULL, " ");
    }
}

// Function to count the number of words in the input string
int countWords(char* input) {
    char* tokens[1000];
    tokenize(input, tokens);
    return strlen(tokens);
}

// Function to convert the input string to uppercase
void convertToUpperCase(char* input) {
    for (int i = 0; i < strlen(input); i++) {
        input[i] = toupper(input[i]);
    }
}

int main() {
    char input[1000];
    scanf("%s", input);
    int count = countWords(input);
    printf("%d\n", count);
    convertToUpperCase(input);
    printf("%s\n", input);
    return 0;
}
