```go
package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	var n, k int
	for _, args := range os.Args[1:] {
		if args == "-" {
			continue
		}
		args = args[1 : len(args)-1]
		vars := strings.Split(args, " ")
		n, _ = strconv.Atoi(vars[0])
		k, _ = strconv.Atoi(vars[1])
		arr := make([]int, n)
		for i := 0; i < n; i++ {
			vars = strings.Split(vars[i+2], " ")
			arr[i], _ = strconv.Atoi(vars[0])
		}
		sort.Ints(arr)
		fmt.Println(arr[n-k])
	}
}
