```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int n, k;
    while (scanf("%d %d", &n, &k) != EOF) {
        int arr[n];
        for (int i = 0; i < n; i++) {
            scanf("%d", &arr[i]);
        }
        qsort(arr, n, sizeof(int), (void (*)(void *))cmp);
        printf("%d
", arr[n - k]);
    }
    return 0;
}

int cmp(const void *a, const void *b) {
    return ((*(int *)a) - (*(int *)b));
}
