	var n, k int
	for _, args := range os.Args[1:] {
		if args == "-" {
			continue
		}
		args = args[1 : len(args)-1]
		vars := strings.Split(args, " ")
		n, _ = strconv.Atoi(vars[0])
		k, _ = strconv.Atoi(vars[1])
