```rust
use std::io::{self, Write};
use std::cmp::{max, min};
use std::collections::VecDeque;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let mut n = 0;
    let mut k = 0;
    while let Some(line) = lines.next() {
        if let [n, k] = line.split_whitespace().map(|s| s.parse::<i32>().unwrap()).collect::<Vec<_>>() {
            if n == 0 && k == 0 {
                break;
            }
            let mut arr = Vec::new();
            for _ in 0..n {
                let mut num = String::new();
                io::stdin().read_to_string(&mut num).unwrap();
                arr.push(num.parse::<i32>().unwrap());
            }
            arr.sort_unstable();
            println!("{}", arr[n - k]);
        }
    }
}
