public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int[] a = new int[n + 1];
        int[][] e = new int[m][3];
        for (int i = 1; i <= n; i++) {
            a[i] = Integer.parseInt(br.readLine());
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            e[i][0] = Integer.parseInt(st.nextToken());
            e[i][1] = Integer.parseInt(st.nextToken());
            e[i][2] = Math.min(a[e[i][0]], a[e[i][1]]);
        }
        Arrays.sort(e, (a, b) -> a[2] - b[2]);
        Arrays.reverse(e);
        int[] fa = new int[n + 1];
        int[] sum = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            fa[i] = i;
            sum[i] = 1;
        }
        long ans = 0;
        for (int i = 0; i < m; i++) {
            int fx = fa[e[i][0]];
            int fy = fa[e[i][1]];
            if (fx != fy) {
                ans += (long) sum[fx] * sum[fy] * e[i][2];
                fa[fx] = fy;
                sum[fy] += sum[fx];
            }
        }
        ans *= 2;
        System.out.println(String.format("%.8f", ans / (double) (n * (n - 1))));
    }
}
