  const [n] = line.split(' ').map(Number);
  const arr = Array.from({ length: n }, () => 0);
  for (let i = 0; i < n; i++) {
    arr[Number(input.readLine())]++;
  }
  let left = 1;
  let right = arr[1];
  let res = -1;
  while (left <= right) {
    const mid = (left + right) >> 1;
    let count = 0;
    for (let i = 1; i < 1001; i++) {
      if (arr[i] - mid > 0) {
        count += arr[i] - mid;
      } else if (arr[i] - mid === 0) {
        count++;
      }
    }
    if (count >= mid) {
      res = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  if (res === -1) {
    console.log(-1);
  } else {
    for (let i = res; i <= arr[1]; i++) {
      console.log(i);
    }
  }
  input.close();
});
