  input: process.stdin,
  output: process.stdout
});

rl.on('line', (line) => {
  const [n] = line.split(' ').map(Number);
  const invalid_array = Array.from({ length: 10 }, (_, i) => i);

  let ans = 0;
  for (let i = 0; i < n; i++) {
    const a = +line;
    ans ^= get_nim(invalid_array[a]);
  }

  console.log(ans ? 'Furlo' : 'Rublo');
  rl.close();
});

