    let mut n = String::new();
    reader.read_line(&mut n).unwrap();
    let n: usize = n.trim().parse().unwrap();

    let mut invalid_array: HashMap<usize, usize> = HashMap::new();
    let mut ans = 0;

    for _ in 0..n {
