        reader.read_line(&mut a).unwrap();
        let a: usize = a.trim().parse().unwrap();

        ans ^= get_nim(invalid_array[a]);
    }

    if ans == 1 {
        writeln!(io::stdout(), "Furlo").unwrap();
    } else {
        writeln!(io::stdout(), "Rublo").unwrap();
    }
}

