```rust
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::fs::File;

fn main() {
    let mut file = File::open("input.txt").unwrap();
    let reader = BufReader::new(&file);
    let mut writer = BufWriter::new(File::create("output.txt").unwrap());

    for line in reader.lines() {
        let line = line.unwrap();
        let mut parts: Vec<_> = line.split_whitespace().collect();
        let n: usize = parts[0].parse().unwrap();
        let m: usize = parts[1].parse().unwrap();

        if n == 0 && m == 0 {
            break;
        }

        for _ in 1..=n {
            let mut parts: Vec<_> = parts[2..].split_whitespace().collect();
            let u: usize = parts[0].parse().unwrap();
            let v: usize = parts[1].parse().unwrap();
            writeln!(writer, "{} {}", u, v).unwrap();
        }

        for _ in 1..=m {
            let mut parts: Vec<_> = parts[2..].split_whitespace().collect();
            let u: usize = parts[0].parse().unwrap();
            let v: usize = parts[1].parse().unwrap();
            writeln!(writer, "{} {}", u, v).unwrap();
        }

        if n == m {
            writeln!(writer, "Yes").unwrap();
        } else {
            writeln!(writer, "No").unwrap();
        }

        parts.clear();
    }
}
