def searchInRange(arr: list, start: int, end: int) -> int:
    for i in range(start, end + 1):
        if i in arr:
            return i
    return -1

n, k = [int(item) for item in input().split(' ')]
holidays = [int(item) for item in input().split(' ')]
del holidays[:1]  # Assuming this is to remove the first element if it's not needed
ans, start, end = 0, 1, k

while start <= n:
    day = searchInRange(holidays, start, end)
    if day == -1 and start + k - 1 > n:
        break
    if day == -1:
        start = end + 1
    else:
        start = day + 1

    end = start + k - 1 if start + k - 1 <= n else n
    ans += 1

print(ans)
