    while stk and lst[stk[-1]] > lst[i]:
        pse[stk.pop()] = i
    stk.append(i)
for i in range(n):
    ans[nse[i] - pse[i] - 1] = max(lst[i], ans[nse[i] - pse[i] - 1])
mnow = ans[n]
for i in range(n, -1, -1):
    mnow = max(mnow, ans[i])
    ans[i] = mnow
print(' '.join(map(str, ans[1:])))


