import math
global n, m, d, a
d = []
a = []

def intdec(x):
    return int(x) - 1

def check(x):
    global n, m, d, a
    vis = [0] * m
    seq = []
    h = 0; cnt = 0
    for i in range(x, -1, -1):
        if d[i] < 0 or vis[d[i]]:
            if len(seq) <= h:
                pass
            else:
                cnt += 1
                # Corrected indexing error
                if cnt == a[seq[cnt - 1]]:  # Changed seq[h] to seq[cnt - 1]
                    h += 1
                    cnt = 0
        else:
            vis[d[i]] = 1
            seq.append(d[i])
    if h < m or vis.count(0):
        return 0
    else:
        return 1

def solve():
    global n, m, d, a
    l = -1
    r = n
    while l < r - 1:
        mid = (l + r) // 2
        if check(mid):
            r = mid
        else:
            l = mid
    if r == n:
        r = -2
    return r

def main():
    global n, m, d, a
    n, m = map(int, input().split())
    d = list(map(intdec, input().split()))
    a = list(map(int, input().split()))
    print(solve() + 1)

