    u = getpar(par,u)
    v = getpar(par,v)
    par[u] = v
    sz[v] += sz[u]
    use[v] += use[u]

def solve(fp):
    par = [i for i in range(n+1)]
    sz = [1 for i in range(n+1)]
    use = [use_count[i] for i in range(n+1)]
    for edge in edges:
        if edge[2] < fp:
            unite(par,sz,use,edge[0],edge[1])
    total_use = sum(use_count)
    for i in range(n+1):
        p = getpar(par,i)
        if(p == i):
            if(total_use - use[p] < sz[p]):
                return False
    return True

while lo < hi:
