    for p in primes:
        d[p] = 0
    # 
    for p in primes:
        if p > x and p > y and p > z:
            break
        while x%p == 0:
            x /= p
            d[p] += 1
        while y%p == 0:
            y /= p
            d[p] += 1
        while z%p == 0:
            z /= p
            d[p] += 1
    ans = 1
    for p in primes:
        ans *= d[p] + 1
    return ans
