namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            Scanner scanner = new Scanner(System.Console);
            scanner.SetPrompt("Enter a string: ");
            scanner.SetTerminal(true);

            scanner.On("line", (line) =>
            {
                string[] words = line.Split(' ');
                int q = 0;

                foreach (string word in words)
                {
                    int t = reserve(word, 8);
                    int v = q - t;
                    if (v < 0)
                        v += 256;
                    Console.WriteLine(v);
                    q = t;
                }
            });

            scanner.On("close", () =>
            {
                scanner.Close();
            });
        }

        static int reserve(string t, int n)
        {
            string s = t.ToString("X2").PadLeft(n, '0');
            return int.Parse(s, System.Globalization.NumberStyles.HexNumber);
        }
    }
}
