	if k > 0 {
		static kDiv := k / (m - 1)
		x = n - kDiv + 1
		if k % (m - 1) != 0 {
			x -= 1
			if x%2 == 0 {
				y = 2 + k % (m - 1) - 1
			} else {
				y = m - k % (m - 1) + 1
			}
		} else {
			if x%2 == 0 {
				y = m
			} else {
				y = 2
			}
		}
	}

