use std::io::{self, Write};

fn main() {
    let mut n = String::new();
    let mut m = String::new();
    let mut k = String::new();

    io::stdin().read_line(&mut n).unwrap();
    let n: i64 = match n.trim().parse() {
        Ok(num) => num,
        Err(_) => {
            println!("Invalid input");
            return;
        }
    };

    io::stdin().read_line(&mut m).unwrap();
    let m: i64 = match m.trim().parse() {
        Ok(num) => num,
        Err(_) => {
            println!("Invalid input");
            return;
        }
    };

    io::stdin().read_line(&mut k).unwrap();
    let k: i64 = match k.trim().parse() {
        Ok(num) => num,
        Err(_) => {
            println!("Invalid input");
            return;
        }
    };

    let mut x = 1;
    let mut y = 1;

    if k < n {
        x += k;
        k = 0;
    } else {
        x += n - 1;
        k -= n - 1;
    }

    if k > 0 {
        let static kDiv = k / (m - 1);
        x = n - kDiv + 1;
        if k % (m - 1) != 0 {
            x -= 1;
            if x % 2 == 0 {
                y = 2 + k % (m - 1) - 1;
            } else {
                y = m - k % (m - 1) + 1;
            }
        } else {
            if x % 2 == 0 {
                y = m;
            } else {
                y = 2;
            }
        }
    }

    writeln!(io::stdout(), "{} {}", x, y).unwrap();
}
