void qsort(int arr[], int n) {
    if (n <= 1) return;
    int pivot = arr[0];
    int i = 0, j = n - 1;
    while (i <= j) {
        while (arr[i] < pivot) i++;
        while (arr[j] > pivot) j--;
        if (i <= j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }
    }
    qsort(arr, i);
    qsort(&arr[i], n - i);
}
