#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    int n, max;
    scanf("%d %d", &n, &max);

    int need[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &need[i]);
    }

    qsort(need, n, sizeof(int), compare);

    int ans = 0;
    for (int i = 0; i <= n; i++) {
        while (max * 2 < need[i]) {
            max *= 2;
            ans++;
        }
        max = max > need[i] ? max : need[i];
    }

    printf("%d
", ans);

    return 0;
}

int compare(const void *a, const void *b) {
    return ((int *)a) - ((int *)b);
