	"strconv"
	"strings"
)

func main() {
	var input string
	var n, k int
	var arr []string
	var result string

	_, err := fmt.Scanf("%s", &input)
	if err != nil {
		fmt.Println(err)
		return
	}

	_, err = fmt.Scanf("%d %d", &n, &k)
	if err != nil {
		fmt.Println(err)
		return
	}

	arr = strings.Split(input, "")

	for i := 0; i < n; i++ {
		if arr[i] == "B" {
			result += "B"
			k--
		} else {
			result += arr[i]
		}
		if k == 0 {
			break
		}
	}

	fmt.Println(result)
