    std::vector<std::vector<bool>> visited(m, std::vector<bool>(n, false));

    // Create a priority queue to store the cells to be visited
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::function<int(const std::pair<int, int>&, const std::pair<int, int>&)>> heap;
