    std::vector<std::pair<int, int>> getNeighbors(int row, int col) {
        std::vector<std::pair<int, int>> neighbors;
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                if (i == 0 && j == 0) continue;
                neighbors.push_back({row + i, col + j});
            }
        }
        return neighbors;
    }

    // Function to find the minimum time to reach the goal
    int findMinTime() {
        while (!heap.empty()) {
            int row = heap.top().first;
            int col = heap.top().second;
