import "fmt"

package main

func countGood(nums []int, k int) int {
    ans := 0
    map := make(map[int]int)
    j := 0
    countPairs := 0

    for i := 0; i <= len(nums); i++ {
        if map[nums[i]] != 0 {
            val := map[nums[i]]
            //to replace the  the previous pair with new pairs
            countPairs -= ((long) val * (val - 1) / 2)
            map[nums[i]]++
            val = map[nums[i]]
            countPairs += ((long) val * (val - 1) / 2)
        } else {
            map[nums[i]] = 1
        }

        // System.out.println(countPairs)
         //sliding the window to right 
        for j <= i && countPairs >= k {
            cur := map[nums[j]]
            countPairs -= (long) cur * (cur - 1) / 2
            map[nums[j]]--
            cur = map[nums[j]]
            countPairs += (long) (cur ) * (cur -1) / 2
            j++
            ans += (len(nums) - i)
        }

    }
    return ans
}

func main() {
    nums := []int{1, 1, 1, 1, 1}
    k := 10
    fmt.Println(countGood(nums, k))
