#include <iostream>
#include <vector>

class Solution {
public:
    double average(const std::vector<int>& salary) {
        int n = salary.size(), sum = 0, Min = INT_MAX, Max = INT_MIN;
        for (int i : salary) {
            Max = std::max(Max, i);
            Min = std::min(Min, i);
            sum += i;
        }
        sum -= (Min + Max);
        return static_cast<double>(sum) / (n - 2.0);
    }
};

int main() {
    std::vector<int> salary = {4000, 3000, 1000, 2000};
