class Solution {
    public int maximumRows(int[][] matrix, int cols) {
        int[][] mat = new int[matrix.length][cols];
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < cols; j++) {
                mat[i][j] = matrix[i][j];
