    private void helper(int[][] mat, int cols, int count, int[] tans, int ans) {
        if (count == cols) {
            ans = Math.max(ans, find(mat));
            return;
        }
        for (int i = 0; i < mat.length; i++) {
            if (tans[i] == 0) {
                tans[i] = 1;
                helper(mat, cols, count + 1, tans, ans);
                tans[i] = 0;
            }
        }
    }

    private int find(int[][] mat) {
