import kotlin.math.max

class Solution {
    private val comb = mutableListOf<MutableList<Int>>()

    fun find(mat1: List<List<Int>>): Int {
        var c = 0
        for (i in mat1.indices) {
            val flg = mat1[i].all { it == 0 }
            if (!flg) c++
        }
        return c
    }

    fun find_ans(mat: List<List<Int>>): Int {
        var ans = 0
        for (i in comb.indices) {
            val temp = comb[i]
            val mat1 = mat
            for (j in temp.indices) {
                val col_val = temp[j]
                for (k in mat1.indices) {
                    mat1[k][col_val] = 0
                }
            }
            ans = maxOf(ans, find(mat1))
        }
        return ans
    }

    fun helper(mat: List<List<Int>>, cols: Int, count: Int, idx: Int, tans: MutableList<Int>) {
        val col = mat[0].size
        if (count == cols) {
            comb.add(tans.toList())
            return
        }
        if (idx >= col) return
        helper(mat, cols, count, idx + 1, tans)
        tans.add(idx)
        helper(mat, cols, count + 1, idx + 1, tans)
    }

    fun maximumRows(mat: List<List<Int>>, cols: Int): Int {
        val tans = mutableListOf<Int>()
        helper(mat, cols, 0, 0, tans)
        return find_ans(mat)
    }
