class Solution {
public:
    std::vector<std::vector<int>> generateMatrix(int n) {
        std::vector<std::vector<int>> mat(n, std::vector<int>(n, 0));

        int startingRow = 0;
        int endingRow = n - 1;
        int startingCol = 0;
        int endingCol = n - 1;
        int k = 1;
        int last = n * n;

        while (k <= last) {
            for (int i = startingCol; k <= last; i++, k++) {
                mat[startingRow][i] = k;
            }
            startingRow++;

            for (int i = startingRow; k <= last; i++, k++) {
                mat[i][endingCol] = k;
            }
            endingCol--;

            for (int i = endingCol; k <= last; i--, k++) {
                mat[endingRow][i] = k;
            }
            endingRow--;

            for (int i = endingRow; k <= last; i--, k++) {
                mat[i][startingCol] = k;
            }
            startingCol++;
        }

        return mat;
    }
