class Solution {
    /**
     * @param {number[][]} image
     * @param {number} sr
     * @param {number} sc
     * @param {number} color
     * @return {number[][]}
     */
    bfs(prevcolor, row, col, color, visited, image) {
        // it'll ease the work
        const queue = [];
        queue.push([row, col]);
        visited[row][col] = 1;

        while (queue.length > 0) {
            row = queue.shift()[0];
            col = queue.shift()[1];
            if (image[row][col] === prevcolor) {
                image[row][col] = color;

            // up
            if (row - 1 >= 0 && !visited[row - 1][col] && image[row - 1][col] === prevcolor) {
                queue.push([row - 1, col]);
                visited[row - 1][col] = 1;
            }

            // right
            if (col + 1 < image[0].length && !visited[row][col + 1] && image[row][col + 1] === prevcolor) {
                queue.push([row, col + 1]);
                visited[row][col + 1] = 1;
            }

            //down
            if (row + 1 < image.length && !visited[row + 1][col] && image[row + 1][col] === prevcolor) {
                queue.push([row + 1, col]);
                visited[row + 1][col] = 1;
            }

            // left
            if (col - 1 >= 0 && !visited[row][col - 1] && image[row][col - 1] === prevcolor) {
                queue.push([row, col - 1]);
                visited[row][col - 1] = 1;
            }
        }
