import java.util.*;

class Solution {
    public int shortestBridge(int[][] grid) {
        int n = grid.length;
        int[][] vis = new int[n][n];
        int ans = 1e9;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && vis[i][j] == 0) {
                    dfs(i, j, vis, grid);
                    ans = Math.min(ans, bfs(i, j, vis, grid));
                }
            }
        }
        return ans;
    }

    private void dfs(int row, int col, int[][] vis, int[][] grid) {
        int n = vis.length;
        vis[row][col] = 1;
        for (int i = 0; i < 4; i++) {
            int nr = row + dr[i];
            int nc = col + dc[i];
            if (nr >= 0 && nc >= 0 && nr < n && nc < n && vis[nr][nc] == 0 && grid[nr][nc] == 1) {
                dfs(nr, nc, vis, grid);
            }
        }
    }

    private int bfs(int row, int col, int[][] vis, int[][] grid) {
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{row, col});
        vis[row][col] = 1;
        int[] dr = {0, 0, -1, 1};
        int[] dc = {1, -1, 0, 0};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nc >= 0 && nr < vis.length && nc < vis[0].length && vis[nr][nc] == 0 && grid[nr][nc] == 1) {
                    vis[nr][nc] = 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        int dist = 0;
        while (true) {
            boolean flag = false;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr >= 0 && nc >= 0 && nr < vis.length && nc < vis[0].length && vis[nr][nc] == 0 && grid[nr][nc] == 1) {
                    flag = true;
                    break;
                }
            }
            if (!flag) {
                return dist;
            }
            dist++;
        }
    }
}
