import java.util.*

class Solution {
    fun shortestBridge(grid: Array<IntArray>): Int {
        val n = grid.size
        val vis = Array(n) { IntArray(n) { 0 } }
        var ans = Int.MAX_VALUE
        for (i in 0 until n) {
            for (j in 0 until n) {
                if (grid[i][j] == 1 && vis[i][j] == 0) {
                    dfs(i, j, vis, grid)
                    ans = minOf(ans, bfs(i, j, vis, grid))
                }
            }
        }
        return ans
    }

    private fun dfs(row: Int, col: Int, vis: Array<IntArray>, grid: Array<IntArray>) {
