/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
/**
 * @param {TreeNode} root
 * @param {number[]} queries
 * @return {number[][]}
 */
public List<List<Integer>> closestNodes(TreeNode root, int[] queries) {
    List<Integer> bv = new ArrayList<>();
    List<List<Integer>> ans = new ArrayList<>();

    dfs(root, bv);

    for (int q : queries) {
        int lb = min1(bv, q);
        int ub = max1(bv, q);
        ans.add(Arrays.asList(lb, ub));
    }

    return ans;
}

private void dfs(TreeNode root, List<Integer> bv) {
    if (root == null) return;
    if (root.left) dfs(root.left, bv);
    bv.add(root.val);
    if (root.right) dfs(root.right, bv);
}

