    std::string destCity(std::vector<std::vector<std::string>>& paths) {
        std::unordered_set<std::string> st;
        for (const auto& row : paths) {
            st.insert(row[0]);
        }
        for (const auto& row : paths) {
            if (st.count(row[0]) > 0) {
                st.erase(row[0]);
            }
        }
        return *st.begin();
    }
};
