class Solution {
    /**
     * @param {number[]} nums - The array of numbers.
     * @param {number} target - The target sum.
     * @returns {number} The number of ways to reach the target sum.
     */
    findTargetSumWays(nums, target) {
        // idx, target -> no of ways
        const memo = {};
        return this.calculate(nums, target, 0, memo);
    }

    /**
     * @param {number[]} nums - The array of numbers.
     * @param {number} target - The target sum.
     * @param {number} idx - The index of the current number.
     * @param {object} memo - The memoization object.
     * @returns {number} The number of ways to reach the target sum.
     */
    calculate(nums, target, idx, memo) {
        if (idx === nums.length) return target === 0;
        if (memo.hasOwnProperty(`${idx}-${target}`)) return memo[`${idx}-${target}`];

        const positive = this.calculate(nums, target + nums[idx], idx + 1, memo);
        const negative = this.calculate(nums, target - nums[idx], idx + 1, memo);

        memo[`${idx}-${target}`] = positive + negative;
        return memo[`${idx}-${target}`];
    }
}

