class Solution {
    /**
     * @param {int[]} nums - The array of numbers.
     * @param {int} target - The target sum.
     * @returns {int} The number of ways to reach the target sum.
     */
    public int findTargetSumWays(int[] nums, int target) {
        // idx, target -> no of ways
        Map<Pair<Integer, Integer>, Integer> memo = new HashMap<>();
        return calculate(nums, target, 0, memo);
    }

    /**
     * @param {int[]} nums - The array of numbers.
     * @param {int} target - The target sum.
     * @param {int} idx - The index of the current number.
     * @param {Map<Pair<Integer, Integer>, Integer>} memo - The memoization map.
     * @returns {int} The number of ways to reach the target sum.
     */
    private int calculate(int[] nums, int target, int idx, Map<Pair<Integer, Integer>, Integer> memo) {
        if (idx == nums.length) return target == 0;
        if (memo.containsKey(new Pair<>(idx, target))) return memo.get(new Pair<>(idx, target));

        int positive = calculate(nums, target + nums[idx], idx + 1, memo);
        int negative = calculate(nums, target - nums[idx], idx + 1, memo);

        memo.put(new Pair<>(idx, target), positive + negative);
        return memo.get(new Pair<>(idx, target));
    }
}

