use std::collections::HashMap;

class Solution {
    /**
     * @param {number[]} nums - The array of numbers.
     * @param {number} target - The target sum.
     * @returns {number} The number of ways to reach the target sum.
     */
    find_target_sum_ways(nums: &Vec<i32>, target: i32) -> i32 {
        // idx, target -> no of ways
        let memo = HashMap::new();
        return self.calculate(nums, target, 0, &memo);
    }

    /**
     * @param {number[]} nums - The array of numbers.
     * @param {number} target - The target sum.
     * @param {number} idx - The index of the current number.
     * @param {&HashMap<(i32, i32), i32>} memo - The memoization hash map.
     * @returns {i32} The number of ways to reach the target sum.
     */
    calculate(nums: &Vec<i32>, target: i32, idx: i32, memo: &HashMap<(i32, i32), i32>) -> i32 {
        if idx == nums.len() {
            return target == 0;
        }
        if let memo_entry = memo.get(&(idx, target)) {
            return *memo_entry;
        }

        let positive = self.calculate(nums, target + nums[idx], idx + 1, memo);
        let negative = self.calculate(nums, target - nums[idx], idx + 1, memo);

        *memo.entry((idx, target)).or_insert(positive + negative);
        return *memo.get(&(idx, target));
    }
}

