        for (let i = 0; i < n; i++) {
            for (let j = 0; j < m; j++) {
                if (mat[i][j] === 0) dp[i][j] = 0;
                else {
                    if (i > 0) dp[i][j] = Math.min(dp[i][j], dp[i - 1][j] + 1); // Top
                    if (j > 0) dp[i][j] = Math.min(dp[i][j], dp[i][j - 1] + 1); // Left
                }
            }
        }

        // Reverse 
        for (let i = n - 1; i >= 0; i--) {
            for (let j = m - 1; j >= 0; j--) {
                if (mat[i][j] === 0) dp[i][j] = INT_MAX - 1;
                else {
                    if (i < n - 1) dp[i][j] = Math.min(dp[i][j], dp[i + 1][j] + 1); // Bottom
                    if (j < m - 1) dp[i][j] = Math.min(dp[i][j], dp[i][j + 1] + 1); // Right
                }
            }
        }
