class Solution {
    pub fn closest_primes(left: i32, right: i32) -> Vec<i32> {
        if left == 1 { left += 1 }
        let mut v = vec![true; right + 1];
        for i in 2..(left as i32).sqrt() as i32 {
            if v[i] {
                for j in (i * i)..right by i {
                    v[j] = false
                }
            }
        }
        let mut i = left;
        let mut j = i;
        let mut a = -1;
        let mut b = -1;
        let mut k = i32::MAX;
        while i <= right {
            if v[i] {
                break
            }
            i += 1
        }
        j = i;
        while j <= right {
            if v[j] {
                if j - i < k {
                    k = j - i;
                    a = i;
                    b = j;
                }
                i = j;
            }
            j += 1
        }
        vec![a, b]
    }
}

