func shortestBridge(grid [][]int) int {
	rows := len(grid)
	cols := len(grid[0])
	vis := make([][]bool, rows)
	for i := range vis {
		vis[i] = make([]bool, cols)
	}
	q := [][]int{}
	for i := 0; i < rows; i++ {
		for j := 0; j < cols; j++ {
			if grid[i][j] == 1 && !vis[i][j] {
				q = append(q, []int{i, j})
				vis[i][j] = true
				for len(q) > 0 {
					r, c := q[0][0], q[0][1]
					q = q[1:]
					for _, dr := range [-1, 0, 1] {
						for _, dc := range [-1, 0, 1] {
							nr, nc := r+dr, c+dc
							if nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1 && !vis[nr][nc] {
								vis[nr][nc] = true
								q = append(q, []int{nr, nc})
							}
						}
					}
				}
			}
		}
	}
	ans := int(1e9)
	for i := 0; i < rows; i++ {
		for j := 0; j < cols; j++ {
			if grid[i][j] == 1 {
				for dr := -1; dr <= 1; dr++ {
					for dc := -1; dc <= 1; dc++ {
						nr, nc := i+dr, j+dc
						if nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 1 {
							ans = min(ans, abs(i-nr)+abs(j-nc))
						}
