```java
import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        int n = nums.length;
        int ans = 0;
        Map<Integer, Map<Integer, Integer>> dp = new HashMap<>();

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                int diff = nums[i] - nums[j];
                dp.putIfAbsent(i, new HashMap<>());
                dp.get(i).put(diff, dp.getOrDefault(j, new HashMap<>()).getOrDefault(diff, 0) + 1);
            }
            ans += dp.get(i).values().stream().mapToInt(Integer::intValue).sum() - i;
        }
        return ans;
    }
}
