    def fizzBuzz(self, n: int) -> List[str]:
        arr = []
        self.helperMethod(n, arr)
        return arr

    def helperMethod(self, n, arr):
        for i in range(1, n+1):
            if i % 3 == 0 and i % 5 == 0:
                arr.append("FizzBuzz")
            elif i % 3 == 0:
                arr.append("Fizz")
            elif i % 5 == 0:
                arr.append("Buzz")
            else:
                arr.append(str(i))
```



